mapper.select:
select

from yh_assess_result
where user_code = #{userCode}
and assess = #{assess,jdbcType=INTEGER}
and is_falg = 2 order by qtime desc limit 1

select count(1)
from yh_assess_result
where assess = #{assess,jdbcType=INTEGER}

      and user_code = #{userCode}

  and is_falg = 2

select yur.user_code, yur.user_name, yur.mobile, yur.`name`, yar.age, if(yar.sex=1,'女','男')as sex, yot.Org_Name, yar.qtime, yar.answer, yar.score, yar.scoreL, yar.state from
( select yar1.user_code, yar1.age, yar1.sex, yar1.score, yar1.scoreL, yar1.state, yar1.qtime, yar1.answer from yh_assess_result yar1 inner join (select user_code, max(qtime)as qtime from yh_assess_result where assess = #{assId} and is_falg = 2 group by user_code) yar2 on yar1.user_code = yar2.user_code and yar1.qtime = yar2.qtime ) yar
(select user_code, age, sex, score, scoreL, qtime, state, answer from yh_assess_result where assess = #{assId} and is_falg = 2) yar
left join yh_user_reginfo yur on yar.user_code = yur.user_code left join yh_user_make_card yumc on yumc.User_Code = yur.user_code left join yh_user_admin_info yuai on yuai.id = yumc.doctor left join yh_org_tree yot on yot.Org_Code = yur.Org_Code
inner join ( select user_code from yh_user_group_info where
(group_id = #{item.group} and group_level = #{item.grouplevel})
group by user_code )yugi on yugi.user_code = yur.user_code
where yur.User_Type = 5
#{item}
and yuai.user_code = #{doctor}
and lock_flag = #{lockFlag}
and yar.sex = #{gender}
and DATE_FORMAT(yur.birth_date,'%Y-%m-%d') <= DATE_SUB(CURDATE(),INTERVAL #{minage} YEAR)
and DATE_FORMAT(yur.birth_date,'%Y-%m-%d') > DATE_SUB(CURDATE(),INTERVAL #{maxage} YEAR)
and yur.reg_time >= #{minregTime}
and yur.reg_time <= #{maxregTime}
and yar.qtime >= #{minExportDate}
and yar.qtime <= #{maxExportDate}
order by yar.qtime desc
